add_filter( 'is_protected_meta', 'perfectpixel_show_protected_meta', 20, 3 );
add_filter( 'acf/settings/remove_wp_meta_box', '__return_false' );

function perfectpixel_show_protected_meta( $protected, $meta_key, $meta_type ) {
	if ( ! is_admin() || 'post' !== $meta_type || ! current_user_can( 'manage_options' ) || ! function_exists( 'get_current_screen' ) ) {
		return $protected;
	}
	$screen = get_current_screen();
	return ( $screen && 'product' === $screen->id ) ? false : $protected;
}
